import re
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo

UTC = timezone.utc
WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
_LOCAL_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2})")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_HM_RE = re.compile(r"([0-9]{2}):([0-9]{2})")
MIN_YEAR, MAX_YEAR = 1900, 2200


def load_zone(name):
    try:
        return ZoneInfo(name)
    except Exception:
        return None


def parse_local(s):
    m = _LOCAL_RE.fullmatch(s)
    if not m:
        return None
    try:
        dt = datetime(*(int(x) for x in m.groups()))
    except ValueError:
        return None
    if not MIN_YEAR <= dt.year <= MAX_YEAR:
        return None
    return dt


def parse_date(s):
    m = _DATE_RE.fullmatch(s)
    if not m:
        return None
    try:
        dt = datetime(*(int(x) for x in m.groups()))
    except ValueError:
        return None
    if not MIN_YEAR <= dt.year <= MAX_YEAR:
        return None
    return dt


def parse_hm(s, allow_24=False):
    """Minutes since midnight for HH:MM, or None."""
    if not isinstance(s, str):
        return None
    m = _HM_RE.fullmatch(s)
    if not m:
        return None
    h, mi = int(m.group(1)), int(m.group(2))
    if mi > 59:
        return None
    if h > 23 and not (allow_24 and h == 24 and mi == 0):
        return None
    return h * 60 + mi


def to_utc(naive, zone, fold=0):
    return naive.replace(tzinfo=zone, fold=fold).astimezone(UTC)


def resolve_local(naive, zone):
    """First-occurrence instant for a local time, or None if the time does not exist."""
    utc = to_utc(naive, zone, 0)
    if utc.astimezone(zone).replace(tzinfo=None) != naive:
        return None
    return utc


def fmt_local(dt):
    return dt.strftime("%Y-%m-%dT%H:%M")


def fmt_in(utc_dt, zone):
    return utc_dt.astimezone(zone).isoformat()


